<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { session, logout, clearSession, ApiError } from '../auth'
type Schedule = {sport:'football'|'nba';provider:'polymarket'|'balldontlie';utc_time:string;enabled:boolean}
type Job = {id:string;kind:string;status:string;due_at:string;attempt_count:number;last_error_code:string|null}
type Worker = {id:string;state:string;last_seen_at:string}
const router=useRouter(), menuOpen=ref(false), revision=ref(0), items=ref<Schedule[]>([]), jobs=ref<Job[]>([]), workers=ref<Worker[]>([]), message=ref(''), busy=ref(false), selected=ref<Job|null>(null), attempts=ref<any[]>([]),system=ref<any>(null),syncRuns=ref<any[]>([]),audit=ref<any[]>([])
const utc8=(v:string)=>{const [h,m]=v.split(':').map(Number);return String((h+8)%24).padStart(2,'0')+':'+String(m).padStart(2,'0')}
const format=(v:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v))
async function api(path:string, options:RequestInit={}) { const response=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store',...options}); const body=await response.json(); if(!response.ok) throw new Error(body?.error?.message || '服务暂不可用'); return body.data }
async function load(){try {const [plan,task,status,info,runs,events]=await Promise.all([api('/sync-schedules'),api('/jobs'),api('/worker-status'),api('/system/status'),api('/sync-runs'),api('/audit-events')]);system.value=info;syncRuns.value=runs.items||[];audit.value=events.items||[];revision.value=plan.revision;items.value=plan.items.map((x:Schedule)=>({...x,utc_time:x.utc_time.slice(0,5)}));jobs.value=task.items;workers.value=status.workers}catch{message.value='加载失败，请检查服务状态。'}}
function add(sport:'football'|'nba'){items.value.push({sport,provider:sport==='football'?'polymarket':'balldontlie',utc_time:'12:00',enabled:true})}
async function save(){busy.value=true;message.value='';try{await api('/sync-schedules',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify({revision:revision.value,items:items.value})});await load();message.value='同步计划已保存。'}catch(e){message.value=e instanceof Error?e.message:'保存失败。'}finally{busy.value=false}}
async function enqueue(sport:'football'|'nba'){try{await api('/sync-runs',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify({sport})});message.value='已提交同步任务，请确认 worker 正在运行。';await load()}catch{message.value='提交同步任务失败。'}}
async function showRuns(job:Job){try{selected.value=job;attempts.value=(await api('/jobs/'+job.id+'/runs')).items}catch{message.value='任务记录加载失败。'}}
async function signOut(){try{await logout();await router.replace('/login')}catch(e){if(e instanceof ApiError&&e.status===401){clearSession();await router.replace('/login')}else message.value='退出请求未确认，请重试。'}}
onMounted(load)
</script>
<template>
<div class="app-layout"><header class="mobile-header"><div class="brand"><span class="brand-mark">P</span> PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header>
<aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand"><span class="brand-mark">P</span> PolySports</div><p class="nav-label">工作台</p><nav aria-label="主导航"><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><RouterLink to="/combos">组合交易</RouterLink><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/history">历史与导出</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside>
<main class="workspace"><div class="workspace-top"><span class="breadcrumb">工作台 / 系统管理</span><div class="account"><span>{{session.username}}</span><button class="text-button" @click="signOut">退出</button></div></div><div class="page-heading"><div><p class="eyebrow">SCHEDULE &amp; STATUS</p><h1>同步与任务</h1><p class="muted">同步时间使用 UTC；任务时间显示为 UTC+8。</p></div></div><p role="status" class="form-message">{{message}}</p>
<section class="welcome-card"><h2>每日同步计划</h2><p>足球赛程仅使用 Polymarket；每一行表示一个同步时间，默认每天两次。每种运动至少保留一个启用时间，修改仅影响未来尚未领取的任务。</p><div v-for="(item,index) in items" :key="index" class="schedule-row"><span>{{item.sport==='football'?'足球':'NBA'}}</span><input v-model="item.utc_time" type="time" :aria-label="`${item.sport} UTC 同步时间`" required><span>UTC · {{utc8(item.utc_time)}} UTC+8</span><button class="text-button" :aria-label="`删除${item.sport}时间`" @click="items.splice(index,1)">删除</button></div><div class="game-tools"><button class="text-button" @click="add('football')">添加足球时间</button><button class="text-button" @click="add('nba')">添加 NBA 时间</button><button class="text-button" :disabled="busy" @click="save">保存计划</button></div></section>
<section class="welcome-card detail"><h2>后台状态</h2><p v-if="!workers.length">未发现 worker 心跳；请启动独立 worker。</p><p v-for="worker in workers" :key="worker.id">{{worker.state==='running'?'运行中':worker.state==='stopping'?'正在停止':'心跳已过期'}} · 最近心跳 {{format(worker.last_seen_at)}} UTC+8</p><div class="game-tools"><button class="text-button" @click="enqueue('football')">手动同步足球</button><button class="text-button" @click="enqueue('nba')">手动同步 NBA</button><button class="text-button" @click="load">刷新状态</button></div></section>
<section v-if="system?.configuration" class="welcome-card detail"><h2>服务配置状态</h2><p>足球赛程来源：Polymarket（无需密钥） · API-Football 赛果绑定密钥：{{system.configuration.football_key_configured?'已配置':'未配置'}} · NBA 数据源：{{system.configuration.nba_key_configured?'已配置':'未配置'}}</p><p>钱包数量：{{system.configuration.wallet_count}} · 组合交易：{{system.configuration.combo_enabled?'已启用':'未启用'}}</p><p>数据库：{{system.database.status}} · 检查时间 {{format(system.database.checked_at)}} UTC+8</p><p v-for="source in system.sources" :key="source.sport">{{source.sport==='football'?'足球':'NBA'}}最近同步：{{source.status}} · 下次计划：{{source.next_due_at ? format(source.next_due_at)+' UTC+8' : '未知'}}</p></section><section class="welcome-card detail"><h2>同步日志</h2><p v-if="!syncRuns.length">暂无同步记录。</p><article v-for="run in syncRuns" :key="run.id" class="market-card"><p>{{run.sport==='football'?'足球':'NBA'}} · {{run.provider}} · {{run.trigger_type || '未知'}} · {{run.status}}</p><p>计划：{{format(run.scheduled_for || run.started_at)}} UTC+8 · 完成：{{run.finished_at ? format(run.finished_at)+' UTC+8' : '尚未完成'}}</p><p v-if="run.window_start && run.window_end">时间窗：{{format(run.window_start)}} 至 {{format(run.window_end)}} UTC+8</p><p>页数 {{run.pages_fetched}} · 收到 {{run.items_received}} · 更新 {{run.items_upserted}} <span v-if="run.error_code">· {{run.error_code}}</span></p></article></section><section class="welcome-card detail"><h2>任务状态</h2><p v-if="!jobs.length">暂无任务。</p><div v-for="job in jobs" :key="job.id" class="schedule-row"><span>{{job.kind==='sync'?'赛程同步':job.kind==='trade_reconcile'?'订单对账':job.kind==='combo_reconcile'?'组合对账':'赛果查询'}}</span><span>{{job.status}}</span><span>{{format(job.due_at)}} UTC+8</span><span>尝试 {{job.attempt_count}} 次</span><span v-if="job.last_error_code">{{job.last_error_code}}</span><button class="text-button" @click="showRuns(job)">查看记录</button></div><div v-if="selected"><h3>任务尝试记录</h3><p v-for="attempt in attempts" :key="attempt.attempt_no">第 {{attempt.attempt_no}} 次 · {{attempt.result}} · {{format(attempt.started_at)}}<span v-if="attempt.error_code"> · {{attempt.error_code}}</span></p></div></section><section class="welcome-card detail"><h2>审计记录</h2><p v-if="!audit.length">暂无审计记录。</p><p v-for="event in audit" :key="event.id">{{format(event.created_at)}} UTC+8 · {{event.action}} · {{event.entity_type || '未知'}}</p></section></main></div>
</template>
